'use strict';

// MODULES //

var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;
var getPrototypeOf = require( '@stdlib/utils/get-prototype-of' );
var Float64Array = require( '@stdlib/array/float64' );


// VARIABLES //

var prototype = getPrototypeOf( Float64Array.prototype );
var lengthGetter = Object.getOwnPropertyDescriptor( prototype, 'length' ).get;


// MAIN //

/**
* Checks intrinsic typed view bounds, including the reused kernel's final increment.
*
* @private
* @param {NonNegativeInteger} N - length
* @param {Float64Array} x - buffer
* @param {integer} stride - stride
* @param {integer} offset - offset
* @returns {boolean} whether native indexing is safe
*/
function canUseNative( N, x, stride, offset ) {
	var length;
	var last;
	var post;

	if ( !isSafeInteger( N ) || N <= 0 || N > 2147483647 ) {
		return false;
	}
	if ( !isSafeInteger( stride ) || stride < -2147483648 || stride > 2147483647 || !isSafeInteger( offset ) || offset < 0 || offset > 2147483647 ) {
		return false;
	}
	try {
		length = lengthGetter.call( x );
	} catch ( err ) { // eslint-disable-line no-unused-vars
		return false;
	}
	if ( getPrototypeOf( x ) !== Float64Array.prototype ) {
		return false;
	}
	last = offset + ((N-1)*stride);
	post = offset + (N*stride);
	return isSafeInteger( last ) && isSafeInteger( post ) && last >= 0 && last < length && offset < length && last <= 2147483647 && post >= -2147483648 && post <= 2147483647;
}


// EXPORTS //

module.exports = canUseNative;
